declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/razorpay.php';
send_cors_headers();$auth=require_auth();if(($_SERVER['REQUEST_METHOD']??'')!=='POST')json_response(405,['success'=>false,'message'=>'Method not allowed.']);$body=get_json_body();$attemptId=trim((string)($body['payment_attempt_id']??''));if($attemptId==='')json_response(422,['success'=>false,'message'=>'Payment attempt is required.']);$userId=auth_user_id($auth);$db=get_db();$db->beginTransaction();try{$stmt=$db->prepare('SELECT p.*,o.user_id,o.order_number,o.payment_status AS order_payment_status,o.status AS order_status FROM payment_attempts p JOIN orders o ON o.id=p.order_id WHERE p.id=:id AND o.user_id=:user FOR UPDATE');$stmt->execute(['id'=>$attemptId,'user'=>$userId]);$attempt=$stmt->fetch();if(!$attempt)json_response(404,['success'=>false,'message'=>'Payment attempt not found.']);if($attempt['provider']!=='online'||$attempt['order_payment_status']!=='pending'||$attempt['order_status']!=='payment_pending')json_response(409,['success'=>false,'message'=>'This order is not awaiting online payment.']);if($attempt['provider_order_id']!==null&&$attempt['provider_order_id']!==''){$db->commit();json_response(200,['success'=>true,'gateway'=>razorpay_is_configured()?'razorpay':'mock','key_id'=>RAZORPAY_KEY_ID,'order_id'=>$attempt['provider_order_id'],'amount'=>(int)round((float)$attempt['amount']*100),'currency'=>$attempt['currency'],'payment_attempt_id'=>$attempt['id']]);}$localMock=!razorpay_is_configured()&&APP_ENV==='local';$providerOrderId='mock_'.$attempt['id'];if(!$localMock){$remote=razorpay_request('POST','orders',['amount'=>(int)round((float)$attempt['amount']*100),'currency'=>$attempt['currency'],'receipt'=>$attempt['order_number'],'notes'=>['conscious_order_id'=>(string)$attempt['order_id']]]);$providerOrderId=trim((string)($remote['id']??''));if($providerOrderId==='')throw new RuntimeException('Razorpay did not return an order id.');}$db->prepare('UPDATE payment_attempts SET provider_order_id=:provider_order,updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['provider_order'=>$providerOrderId,'id'=>$attemptId]);$db->commit();json_response(200,['success'=>true,'gateway'=>$localMock?'mock':'razorpay','key_id'=>RAZORPAY_KEY_ID,'order_id'=>$providerOrderId,'amount'=>(int)round((float)$attempt['amount']*100),'currency'=>$attempt['currency'],'payment_attempt_id'=>$attemptId]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
